  const paint=()=>{lists.forEach((l,i)=>l.innerHTML=groups[i].map(s=>`<li><button data-item="${s}" aria-pressed="${s===picked}">${s}</button></li>`).join(''));say(`準備 ${groups[0].length} / 再生 ${groups[1].length}`)};
