  const finish=()=>{active=false;box.hidden=true};on(board,'pointerup',finish);on(board,'pointercancel',finish);$$('.tile').forEach(b=>on(b,'click',()=>{b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true'));count()}));action=()=>{$$('.tile').forEach(b=>b.setAttribute('aria-pressed','false'));count()};update=count;
