function add(id,category,name,ja,description,scene,controls=[],extra={}){experienceLabs.push(domLab({id,category,name,ja,description,use:extra.use||'違いを確かめたり、選択・編集の手応えを設計するとき。',tip:extra.tip||'操作前後を見比べてください。ボタンやスライダーでも操作できます。',tags:[ja,...(extra.tags||[])],source:extra.source||'https://developer.mozilla.org/en-US/docs/Web/API/Pointer_events',categories:extra.categories||[category,'interaction'],level:'applied',targets:extra.targets||['ui'],contexts:extra.contexts||['navigation'],support:'Pointer Events / HTML / CSS。操作は見本の中で完結します。',...extra},setup,controls,scene,css,{static:true,action:extra.action||'最初から'}))}
add('compare-wipe','image','Image comparison wipe','境界を動かして、二枚を比べる','同じ図柄のカラーとモノクロを重ね、境界をドラッグして比較します。',`<div class="picture"><div class="art">${art}</div><div class="art mono">${art}</div><span class="compare-line"></span></div>`,[c('position','比較の境界 %',0,100,50)],{tags:['比較','ビフォーアフター'],targets:['image'],categories:['image','mask','gesture'],contexts:['commerce','editorial']});
