add('product-config','image','Material configurator','色と素材を、選んで比べる','色の選択とマット・光沢の切り替えで、同じ形の印象を比較します。','<div class="product-demo"><div class="product-object"><strong>MINERALion</strong><small>MATERIAL STUDY / 架空の素材見本</small></div></div><div class="row"><button data-color>青</button><button data-color>緑</button><button data-color>砂</button><button data-material>素材 / マット</button></div>',[],{tags:['選択','商品','素材','色'],targets:['image'],contexts:['commerce'],categories:['image','color','ui']});
add('product-explode','three','Exploded layers','部品を離して、構造を見せる','三つの模式的な部品を離し、重なって見えなかった構造を説明します。','<div class="product-demo"><div class="pieces"><div class="piece">01 / 表面</div><div class="piece">02 / 中間層</div><div class="piece">03 / 台座</div></div></div>',[c('spread','部品の間隔 px',0,45,0)],{tags:['分解図','商品','構造'],targets:['shape'],contexts:['commerce'],categories:['three','layout','motion'],action:'組み立て／分解'});
add('product-hotspots','ui','Product annotations','気になる部分から、説明を読む','図の上に注釈ボタンを置き、選んだ部分の説明を表示します。','<div class="product-demo"><div class="product-object"><strong>MINERALion</strong><small>DETAIL STUDY</small></div></div><button class="hotspot" style="top:30px;left:20%" aria-label="表面の注釈">1</button><button class="hotspot" style="top:65px;right:12%" aria-label="側面の注釈">2</button><button class="hotspot" style="top:100px;left:18%" aria-label="角の注釈">3</button><p class="annotation"></p>',[],{tags:['注釈','商品','説明'],contexts:['commerce'],action:'次の注釈'});
add('edit-sort','gesture','Sortable sequence','つかんで、順序を変える','項目をドラッグして並べ替えます。選択後の移動ボタン、Alt＋左右キーでも同じ順序変更ができます。','<p style="font-size:11px">MIXWELL / PLAY ORDER</p><ol class="edit-items"></ol><div class="row"><button data-prev>← 前へ</button><button data-next>後ろへ →</button></div>',[],{tags:['編集','並べ替え','ドラッグ'],source:'https://www.w3.org/WAI/ARIA/apg/patterns/listbox/examples/listbox-rearrangeable/',categories:['gesture','ui'],tip:'項目を選んで移動するか、移動先へドラッグしてください。'});
add('edit-transfer','gesture','Transfer between lists','二つのリストを行き来する','選んだ項目を別のリストへ移します。ドラッグとボタンで同じ結果になります。','<div class="transfer"><div class="bin"><small>準備</small><ul class="edit-items"></ul></div><div class="bin"><small>再生</small><ul class="edit-items"></ul></div></div><div class="row"><button data-transfer>選択項目を反対側へ ⇄</button></div>',[],{tags:['編集','移動','リスト'],categories:['gesture','ui']});
add('edit-lasso','gesture','Marquee selection','範囲を囲って、まとめて選ぶ','背景から矩形をドラッグし、その範囲に触れた項目を選択します。各ボタンを押しても選択できます。',`<div class="select-board">${Array.from({length:6},(_,i)=>`<button class="tile" style="left:${12+i%3*31}%;top:${15+Math.floor(i/3)*65}px" aria-pressed="false">${String(i+1).padStart(2,'0')}</button>`).join('')}<span class="selection-box" hidden></span></div>`,[],{tags:['編集','範囲選択','複数選択'],categories:['gesture','ui']});
add('edit-guides','gesture','Alignment guides','配置の基準線に、吸い付く','中央に近づくとガイドが現れ、位置が中央へ吸着します。座標スライダーでも動かせます。','<div class="select-board"><span class="guide-line x"></span><span class="guide-line y"></span><div class="guide-object">MIXWELL</div></div>',[c('x','横位置 %',12,88,30),c('y','縦位置 %',22,78,35)],{tags:['編集','ガイド','吸着','整列'],targets:['layout'],categories:['gesture','layout']});
add('search-suggest','ui','Autocomplete suggestions','入力の途中で、候補に出会う','入力した文字を含む候補を表示し、上下キーとEnter、またはクリックで選択します。','<div class="search-demo"><label>名前を探す<input type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" autocomplete="off" placeholder="MI と入力"></label><ul role="listbox" class="suggestions" aria-label="名前の候補" hidden></ul></div>',[],{tags:['検索','探す','入力候補'],source:'https://www.w3.org/WAI/ARIA/apg/patterns/combobox/',contexts:['forms','navigation'],tip:'MI と入力し、下矢印で選んでEnter。Escapeで候補を閉じられます。',action:'MI を試す'});
add('search-highlight','type','Search term highlighting','見つかった言葉を、浮かび上がらせる','検索語に一致する部分を強調し、どこが見つかったかを伝えます。入力文字列をHTMLとして解釈しません。','<div class="search-demo"><label>強調する文字<input type="text" value="M" aria-label="強調する文字"></label><div class="search-results"></div></div>',[],{tags:['検索','探す','強調','ハイライト'],targets:['text'],categories:['type','ui'],source:'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/mark',action:'M を試す'});
add('search-chips','ui','Filter chips','選んだ条件を、小さな札にする','絞り込み条件をチップで表示し、一つずつ解除できます。この例は選択条件のいずれかに一致する方式です。','<div class="search-demo"><div class="row"><button data-tag="文字">文字</button><button data-tag="質感">質感</button><button data-tag="操作">操作</button></div><div class="chip-list" aria-label="選択中の条件"></div><div class="search-results"></div></div>',[],{tags:['検索','探す','絞り込み','チップ'],contexts:['navigation']});
